<template>
<main class="nlu-hub">
 <header class="hub-header"><div class="hub-brand"><img v-if="logo" :src="logo" :alt="brand"/><span v-else>{{brand}}</span></div><div class="hub-heading"><p>{{state.title||'Individual tutoring'}} · {{inPerson?'In person':'Virtual'}}</p><h1>Session Hub</h1><small>{{state.studentName}} <span v-if="grade">· Grade {{grade}}</span> · Appointment #{{state.appointmentId}}</small></div><div class="session-state"><span class="state-dot" :class="{live:state.startedAt&&!closed}"/>{{closed?'Session ended':state.startedAt?'In session':'Ready for session'}}<time>{{elapsed}}</time></div><router-link v-if="!guest" :to="backPath">Back to {{state.host?'my schedule':'my portal'}}</router-link><button v-if="!closed&&(state.startedAt||video||wantsJoin)" class="end" @click="$emit(state.host?'end':'leave')">{{state.host?'End session':'Leave session'}}</button></header>
 <div v-if="error" class="hub-alert" role="alert">{{error}} <button @click="$emit('refresh')">Try again</button></div>
 <div v-if="state.unavailableReason" class="hub-alert" role="alert">{{state.unavailableReason}}</div>
 <p v-if="endNotice&&!closed" class="hub-alert" role="status">{{endNotice}} <button v-if="state.host" @click="$emit('end')">End session</button></p>
 <p v-if="state.needsCompletion" class="hub-alert" role="status">The room closed at the end of its join window. Review the saved attendance to complete this appointment. <button :disabled="busy" @click="$emit('end')">Review &amp; complete session</button></p>
 <div class="hub-columns">
 <aside class="people-column">
  <h2>{{inPerson?'In-person session':'Live participants'}} <span>{{admitted.length?admitted.length+' admitted':''}}</span></h2>
  <div v-if="video" class="participant-video"><VideoSessionRoom ref="media" v-bind="video" :renew-credentials="renewVideo" hide-controls server-managed-end :defer-alone-warning="state.host&&!closed" :equal-tiles-when-remote="false" :is-host-or-cohost="state.host" @connected="$emit('connected')" @disconnected="$emit('disconnected',$event)" @leave-request="$emit(state.host?'end':'leave')" @meeting-ended="$emit('refresh')"/></div>
  <div v-else class="participant-placeholder"><span>{{initials}}</span><strong>{{state.host?'Your session':state.studentName}}</strong><p>{{inPerson?'Your learner works with you in person. Use the same board and materials here.':waitingMessage}}</p><button v-if="!inPerson&&!closed&&!wantsJoin" class="primary" :disabled="busy||!state.available" @click="$emit('join')">{{state.host?'Open tutoring room':'Join tutoring session'}}</button><button v-if="inPerson&&state.host&&!state.startedAt&&!closed" class="primary" :disabled="busy" @click="$emit('start')">Start in-person session</button><p v-if="!inPerson&&!state.available&&!closed">{{windowMessage}}</p></div>
  <p v-if="video" class="connection">{{connected?'Connected to this appointment':'Connecting audio and video…'}}</p>
  <section v-if="state.host&&!inPerson" class="waiting"><h3>Waiting room <span>{{waiting.length}}</span></h3><p v-if="!waiting.length">No one is waiting.</p><article v-for="person in waiting" :key="person.id"><strong>{{person.displayName}}</strong><button :disabled="!connected||busy" @click="$emit('admit',person.id)">Admit</button></article><p v-for="person in admitted" :key="person.id">{{person.displayName}} · {{person.mediaDurationSeconds==null?'Admitted · waiting for video connection':'Connected to this session'}}</p></section>
  <section class="focus-card"><h3>Today’s focus</h3><ol v-if="goals.length"><li v-for="goal in goals.slice(0,4)" :key="goal.id">{{goal.title}}</li></ol><p v-else>{{state.title||'General tutoring'}} · Build confidence through practice.</p></section>
  <section v-if="state.host&&!inPerson&&!closed" class="invitation"><label v-if="joinRecipients?.length">Invited family member<select :value="selectedRecipient" @change="$emit('select-recipient',$event.target.value)"><option value="">Choose family member</option><option v-for="person in joinRecipients" :key="person.id" :value="person.id">{{person.name}}</option></select></label><button :disabled="busy" @click="$emit('copy-link')">Copy family session invitation</button><button v-if="selectedRecipient" :disabled="busy" @click="$emit('revoke-link')">End selected invitation</button><p v-if="linkNotice" role="status">{{linkNotice}}</p><input v-if="manualJoinLink" :value="manualJoinLink" readonly aria-label="Session invitation" @focus="$event.target.select()"/></section>
  <details v-if="state.host&&state.visits?.length" class="history"><summary>Attendance history</summary><p v-for="person in state.visits" :key="person.id">{{person.displayName}} · {{person.status==='admitted'&&person.mediaDurationSeconds==null?'Admission permitted · no connected attendance yet':person.status}}<span v-if="person.mediaDurationSeconds!=null"> · {{Math.round(person.mediaDurationSeconds/60)}} min connected</span></p></details>
  <slot name="attendance"/>
 </aside>
 <TutoringSessionStudio v-if="state.sessionId&&(state.host||state.visit?.status==='admitted')" ref="studio" :key="state.sessionId" :host="state.host" :closed="closed" :request="request" :workspace-request="workspaceRequest" :learning-context="learningContext" :rate-activity="rateActivity" :generate-question="generateQuestion" :read-material="readMaterial"><template #learning><slot name="learning"/></template><template #notes><slot name="notes"/></template><template #progress><slot name="progress"/></template></TutoringSessionStudio>
 <div v-else class="awaiting"><h2>{{closed?'This session has ended':'Your shared learning space'}}</h2><p>{{closed?'Your saved session record stays with this appointment.':'Join this appointment and wait for your tutor to admit you. The lesson opens right here.'}}</p><slot v-if="closed" name="summary"/></div>
 </div>
 <footer class="hub-dock"><span class="dock-context">{{brand}} · {{inPerson?'In person':'Virtual'}} · Session Hub</span><template v-if="video"><button @click="media?.toggleMic()"><Mic :size="19"/>{{media?.publishAudio===false?'Unmute':'Mute'}}</button><button @click="media?.toggleCamera()"><Camera :size="19"/>{{media?.publishVideo===false?'Start camera':'Camera'}}</button><button @click="media?.toggleScreenShare()"><ScreenShare :size="19"/>Share screen</button><button @click="media?.toggleRaiseHand()"><Hand :size="19"/>Raise hand</button></template><button v-if="state.host&&!closed" @click="studio?.whiteboard()"><PenLine :size="19"/>Whiteboard</button><button @click="studio?.showMaterials()"><Files :size="19"/>Materials</button><button @click="studio?.showChat()"><MessageCircle :size="19"/>Chat</button><button v-if="state.host" @click="studio?.showNotes()"><NotebookPen :size="19"/>Session notes</button></footer>
</main>
</template>
<script setup>
import {computed,ref,onMounted,onBeforeUnmount} from 'vue';
import {Mic,Camera,ScreenShare,Hand,PenLine,Files,MessageCircle,NotebookPen} from '@lucide/vue';
import VideoSessionRoom from '../video/VideoSessionRoom.vue';
import TutoringSessionStudio from './TutoringSessionStudio.vue';
const props=defineProps({state:Object,video:Object,connected:Boolean,closed:Boolean,inPerson:Boolean,busy:Boolean,wantsJoin:Boolean,guest:Boolean,brand:String,logo:String,backPath:String,error:String,windowMessage:String,linkNotice:String,manualJoinLink:String,joinRecipients:Array,selectedRecipient:[String,Number],goals:{type:Array,default:()=>[]},learningContext:Object,request:Function,workspaceRequest:Function,rateActivity:Function,generateQuestion:Function,readMaterial:Function,renewVideo:Function});
defineEmits(['refresh','join','start','end','leave','admit','connected','disconnected','copy-link','select-recipient','revoke-link']);
const media=ref(null),studio=ref(null),now=ref(Date.now());let clock;
const waiting=computed(()=>(props.state.visits||[]).filter(p=>p.status==='waiting'&&p.present!==false)),admitted=computed(()=>(props.state.visits||[]).filter(p=>p.status==='admitted'));
const grade=computed(()=>props.learningContext?.tracks?.[0]?.subject?.school_grade);
const initials=computed(()=>(props.state.studentName||'Session').split(' ').slice(0,2).map(s=>s[0]).join(''));
const waitingMessage=computed(()=>props.wantsJoin?(props.state.visit?.status==='admitted'?'Connecting to your tutor…':'You’re in the waiting room for this appointment. Your tutor will admit you.'):'Your camera and microphone connect when you join this appointment.');
const endNotice=computed(()=>{const end=Date.parse(props.state.endAt),close=Date.parse(props.state.closesAt);if(!Number.isFinite(end)||now.value<end-5*60000)return '';if(now.value>=close)return 'This appointment’s join window has closed. Reconnecting is no longer available.';return now.value>=end?'Your scheduled session time has ended. Finish your work and end this session. The room closes 30 minutes after the scheduled end.':'Your scheduled session ends in '+Math.ceil((end-now.value)/60000)+' minutes.';});
const elapsed=computed(()=>{const seconds=props.state.startedAt?Math.max(0,Math.floor(((props.state.endedAt?Date.parse(props.state.endedAt):now.value)-Date.parse(props.state.startedAt))/1000)):0;return [Math.floor(seconds/3600),Math.floor(seconds/60)%60,seconds%60].map(n=>String(n).padStart(2,'0')).join(':');});
onMounted(()=>clock=setInterval(()=>now.value=Date.now(),1000));onBeforeUnmount(()=>clearInterval(clock));
</script>
